#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<int> countPairs(int n, vector<vector<int>>& edges, vector<int>& queries) {
        vector<int> degree(n + 1, 0);
        unordered_map<int, unordered_map<int, int>> freq;
        for (auto& e : edges) {
            int u = e[0], v = e[1];
            degree[u]++;
            degree[v]++;
            if (u > v) swap(u, v);
            freq[u][v]++;
        }

        vector<int> sorted = degree;
        sort(sorted.begin(), sorted.end());
        vector<int> res;
        for (int q : queries) {
            int total = 0;
            int l = 1, r = n;
            while (l < r) {
                if (sorted[l] + sorted[r] <= q) l++;
                else {
                    total += r - l;
                    r--;
                }
            }

            for (auto& [u, mp] : freq)
                for (auto& [v, cnt] : mp)
                    if (degree[u] + degree[v] > q && degree[u] + degree[v] - cnt <= q)
                        total--;

            res.push_back(total);
        }

        return res;
    }
};
